provenance.sourcePrompt:
3D card showcase — three role cards appear one at a time with visible 3D rotation. 16s, 1920x1080, SILENT. CRITICAL: use perspective() function directly in transform, not perspective property, so 3D works in all renderers. Each card continuously rotates on Y axis with slight X tilt. Shiny gloss overlay sweeps. Dark navy background
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@700;900&family=Playfair+Display:wght@700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;}
#scene{
position:relative
background:linear-gradient(160deg,#0d1117 0%,#131a2e 60%,#0a0f1e 100%)
display:flex;align-items:center;justify-content:center
}
/* ── 3D CARD — uses perspective() in transform, not as property ── */
card-stage{
position:absolute
display:flex;flex-direction:column;align-items:center
opacity:0
}
card-wrap{
width:320px;height:460px
position:relative
/* perspective() in transform = works without preserve-3d */
animation:spin3d 3s infinite linear
}
@keyframes spin3d{
0%  { transform: perspective(800px) rotateX(8deg) rotateY(0deg);   }
25% { transform: perspective(800px) rotateX(5deg) rotateY(90deg);  }
50% { transform: perspective(800px) rotateX(8deg) rotateY(180deg); }
75% { transform: perspective(800px) rotateX(5deg) rotateY(270deg); }
100%{ transform: perspective(800px) rotateX(8deg) rotateY(360deg); }
}
card-face{
width:100%;height:100%
background:#ffffff
border-radius:6px
box-shadow:0 40px 90px rgba(0,0,0,0.65), 0 8px 20px rgba(0,0,0,0.30)
overflow:hidden
position:relative
}
card-img{
width:calc(100% - 24px)
height:calc(100% - 24px)
margin:12px
overflow:hidden
border-radius:3px
position:relative
}
card-img img{
width:100%;height:100%
object-fit:cover;display:block
filter:grayscale(10%) contrast(1.06)
}
/* shiny sweep — radial gradient animating top-to-bottom */
card-img::after{
content:""
position:absolute
left:-30%;top:0
width:85%
padding-bottom:85%
border-radius:50%
background:radial-gradient(ellipse at center
rgba(255,255,255,0.35) 0%
rgba(255,255,255,0) 70%)
pointer-events:none
animation:shiny 3s infinite ease-in-out
}
@keyframes shiny{
0%  {transform:translateY(-120%);}
45% {transform:translateY(520px);}
46% {transform:translate(100%,520px);}
90% {transform:translate(100%,-120%);}
100%{transform:translateY(-120%);}
}
/* role label */
role-label{
margin-top:24px
text-align:center
opacity:0;transform:translateY(10px)
}
role-type{
font-family:'Inter',Arial,sans-serif
font-size:12px;font-weight:700
letter-spacing:.32em;text-transform:uppercase
color:rgba(240,236,228,0.42);margin-bottom:8px
}
role-name{
font-family:'Playfair Display',Georgia,serif
font-size:46px;font-weight:700
color:#f0ece4;line-height:.90;letter-spacing:-.01em
}
role-year{
font-family:'Inter',Arial,sans-serif
font-size:13px;font-weight:400
letter-spacing:.20em;text-transform:uppercase
color:rgba(240,236,228,0.32);margin-top:8px
}
#open-fade,#close-fade{
position:absolute;inset:0;z-index:50
background:#0d1117;pointer-events:none
}
#open-fade{opacity:1;}
#close-fade{opacity:0;}
</style>
</head>
<body>
<div id="scene">
<div id="open-fade"></div>
<div id="close-fade"></div>
<div class="card-stage" id="s1">
<div class="card-wrap">
<div class="card-face">
<div class="card-img"><img src="{{img1}}" alt=""></div>
</div>
</div>
<div class="role-label" id="l1">
<div class="role-type">Film · 2014</div>
<div class="role-name">Alan Turing</div>
<div class="role-year">The Imitation Game</div>
</div>
</div>
<div class="card-stage" id="s2">
<div class="card-wrap">
<div class="card-face">
<div class="card-img"><img src="{{img2}}" alt=""></div>
</div>
</div>
<div class="role-label" id="l2">
<div class="role-type">Television · 2010</div>
<div class="role-name">Sherlock Holmes</div>
<div class="role-year">BBC One</div>
</div>
</div>
<div class="card-stage" id="s3">
<div class="card-wrap">
<div class="card-face">
<div class="card-img"><img src="{{img3}}" alt=""></div>
</div>
</div>
<div class="role-label" id="l3">
<div class="role-type">Stage · 2015</div>
<div class="role-name">Hamlet</div>
<div class="role-year">Barbican Theatre, London</div>
</div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
var tl=gsap.timeline()
tl.to('#open-fade',{opacity:0,duration:0.5,ease:'power2.out'},0.0)
/* CARD 1 */
tl.set('#s1',{opacity:1},0.4)
tl.to('#s1',{scale:1,duration:0.65,ease:'back.out(1.3)',startAt:{scale:0.80,opacity:1}},0.4)
tl.to('#l1',{opacity:1,y:0,duration:0.5,ease:'power3.out'},0.75)
tl.to('#l1',{opacity:0,y:-8,duration:0.35,ease:'power2.in'},4.5)
tl.to('#s1',{opacity:0,scale:0.85,duration:0.4,ease:'power2.in'},4.6)
tl.set('#s1',{opacity:0},5.1)
/* CARD 2 */
tl.set('#s2',{opacity:1},5.0)
tl.to('#s2',{scale:1,duration:0.65,ease:'back.out(1.3)',startAt:{scale:0.80,opacity:1}},5.0)
tl.to('#l2',{opacity:1,y:0,duration:0.5,ease:'power3.out'},5.35)
tl.to('#l2',{opacity:0,y:-8,duration:0.35,ease:'power2.in'},9.5)
tl.to('#s2',{opacity:0,scale:0.85,duration:0.4,ease:'power2.in'},9.6)
tl.set('#s2',{opacity:0},10.1)
/* CARD 3 */
tl.set('#s3',{opacity:1},10.0)
tl.to('#s3',{scale:1,duration:0.65,ease:'back.out(1.3)',startAt:{scale:0.80,opacity:1}},10.0)
tl.to('#l3',{opacity:1,y:0,duration:0.5,ease:'power3.out'},10.35)
tl.to('#l3',{opacity:0,y:-8,duration:0.35,ease:'power2.in'},14.5)
tl.to('#s3',{opacity:0,scale:0.85,duration:0.4,ease:'power2.in'},14.6)
tl.to('#close-fade',{opacity:1,duration:0.7,ease:'power2.inOut'},14.8)
tl.set('#close-fade',{opacity:1},15.6)
})
</script>
</body>
</html>
```
